customMethods.script:

for row in self.view.custom.assetStates.selectedData:
	if system.kanoa.lot.unlinkAssetLotState(row['lotStateReasonAssetLinkId'], self.view.custom.security.userId) == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': '%s state has been disabled as there are historical entries asssociated with this lot state.'%row['stateName']})

self.view.refreshBinding("custom.assetStates.data")

return


for row in self.view.custom.lotStateReasons.selectedData:
	retVal, response = system.kanoa.lot.deleteLotStateReason(row['lotStateReasonId'], self.view.custom.security.userId)
	if response == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': 'Lot state reason %s has been disabled as there are historical entries asssociated with this lot state reason'%row['lotStateReasonName']})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Lot state reason %s has been deleted'%row['lotStateReasonName']})

self.view.refreshBinding("custom.lotStateReasons.data")
self.view.custom.lotStateReasons.row = None
self.view.custom.lotStateReasons.col = None

return


for row in self.view.custom.lotStates.selectedData:
	retVal, response = system.kanoa.lot.deleteLotState(row['lotStateId'], self.view.custom.security.userId)
	if response == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': 'Lot state %s has been disabled as there are historical entries asssociated with this lot state'%row['lotStateName']})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Lot state %s has been deleted'%row['lotStateName']})

self.view.refreshBinding("custom.lotStates.data")
self.view.custom.lotStates.row = None
self.view.custom.lotStates.col = None

return

